-- Let's understand the relationship: batsman_scored records runs per ball, and ball_by_ball tells us which striker faced that ball and which team was batting
-- First, let's check how batsman_scored relates to ball_by_ball - do they share the same match_id, over_id, ball_id, innings_no?
SELECT COUNT(*) as batsman_scored_rows FROM batsman_scored;
SELECT COUNT(*) as ball_by_ball_rows FROM ball_by_ball;
